bounded_host_request.command:
set -euo pipefail
root="$HOME/Project/Gserver/projects/TGtumbler/GateApp-Bot"
test "$(docker inspect -f '{{.State.Running}}' deploy-gaybbs-1)" = true || exit 61
owner="$(cat "$root/deploy/secrets/bug_report_userbot_account.txt")"
[[ "$owner" =~ ^[1-9][0-9]{3,18}$ ]] || exit 62
state="$(docker exec deploy-postgres-1 psql -X -v ON_ERROR_STOP=1 -U gace -d gaybbs -Atc "SELECT step||'|'||coalesce(data->>'linkStage','missing')||'|'||CASE WHEN data ? 'shareCode' THEN 'registered' ELSE 'unregistered' END||'|'||coalesce(data->>'linkEditorView','none') FROM public_post_drafts WHERE owner_user_id=$owner AND module='link';" 2>/dev/null)" || exit 63
case "$state" in
 preview\|*\|unregistered\|*) exit 71 ;;
 awaiting_text\|*\|unregistered\|*) exit 72 ;;
 preview\|*\|registered\|*) exit 73 ;;
 cancelled\|*) exit 74 ;;
 "") exit 75 ;;
 *) exit 76 ;;
esac
